create table if not exists public.order_number_sequences (year integer primary key,last_number integer not null default 0,updated_at timestamptz not null default now()); alter table public.orders add column if not exists quotation_id uuid references public.quotations(id) on delete restrict, add column if not exists quotation_version_id uuid references public.quotation_versions(id) on delete restrict, add column if not exists approved_mockup_set_id uuid references public.mockup_sets(id) on delete restrict, add column if not exists company_name text, add column if not exists billing_address text, add column if not exists currency text not null default 'IDR', add column if not exists source_snapshot jsonb not null default '{}'::jsonb, add column if not exists converted_at timestamptz, add column if not exists converted_by uuid, add column if not exists archived_at timestamptz, add column if not exists archived_by uuid, add column if not exists archive_reason text, add column if not exists updated_by uuid; alter table public.order_items add column if not exists quotation_item_id uuid references public.quotation_items(id) on delete set null, add column if not exists variant_name text, add column if not exists pricing_status text not null default 'confirmed', add column if not exists archived_at timestamptz, add column if not exists archived_by uuid, add column if not exists archive_reason text; create table if not exists public.order_item_services (id uuid primary key default gen_random_uuid(),order_item_id uuid not null references public.order_items(id) on delete cascade,quotation_item_service_id uuid references public.quotation_item_services(id) on delete set null,service_name text not null,quantity integer not null check(quantity>0),position text,pricing_status text not null default 'confirmed',unit_price numeric,flat_price numeric,subtotal numeric,notes text,snapshot jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create unique index if not exists orders_one_per_quotation_idx on public.orders(quotation_id) where quotation_id is not null; create index if not exists orders_active_idx on public.orders(created_at desc) where archived_at is null; create index if not exists orders_archive_idx on public.orders(archived_at desc) where archived_at is not null; create index if not exists order_item_services_order_item_idx on public.order_item_services(order_item_id); alter table public.order_item_services enable row level security; drop policy if exists "Staff manage order item services" on public.order_item_services; create policy "Staff manage order item services" on public.order_item_services for all to authenticated using (public.has_staff_role(array['owner','superadmin','super_admin','sales_admin','admin'])) with check (public.has_staff_role(array['owner','superadmin','super_admin','sales_admin','admin']));;
